package main

import (
	"context"
	"crypto/aes"
	"crypto/cipher"
	"encoding/hex"
	"fmt"
	"html/template"
	"log"
	"net/http"
	"os"
	"sync"

	"github.com/segmentio/kafka-go"
)

var (
	// Static encryption key used for all message decryption
	// This key is shared across all consumer group instances
	encryptionKey = []byte("0123456789abcdef0123456789abcdef") // AES-256
	nonce         = []byte("unique nonce")                      // 12 bytes, reused
	gcm           cipher.AEAD
	messageStore  = &MessageStore{messages: make([]string, 0, 100)}
)

type MessageStore struct {
	mu       sync.RWMutex
	messages []string
}

func (ms *MessageStore) Add(msg string) {
	ms.mu.Lock()
	defer ms.mu.Unlock()
	if len(ms.messages) >= 100 {
		ms.messages = ms.messages[1:]
	}
	ms.messages = append(ms.messages, msg)
}

func (ms *MessageStore) GetAll() []string {
	ms.mu.RLock()
	defer ms.mu.RUnlock()
	result := make([]string, len(ms.messages))
	copy(result, ms.messages)
	return result
}

func init() {
	block, err := aes.NewCipher(encryptionKey)
	if err != nil {
		log.Fatal(err)
	}
	gcm, err = cipher.NewGCMWithNonceSize(block, 12)
	if err != nil {
		log.Fatal(err)
	}
}

func decryptMessage(ciphertext []byte) (string, error) {
	// Nonce reuse: same nonce used for every decryption
	// This enables known-plaintext attacks to recover keystream
	plaintext, err := gcm.Open(nil, nonce, ciphertext, nil)
	if err != nil {
		return "", fmt.Errorf("decryption failed: %w", err)
	}
	return string(plaintext), nil
}

func consumeMessages(ctx context.Context) {
	broker := os.Getenv("KAFKA_BROKER")
	if broker == "" {
		broker = "localhost:9092"
	}

	reader := kafka.NewReader(kafka.ReaderConfig{
		Brokers:  []string{broker},
		Topic:    "encrypted-events",
		GroupID:  "stream-processor-group",
		MinBytes: 1e3,
		MaxBytes: 10e6,
	})
	defer reader.Close()

	for {
		select {
		case <-ctx.Done():
			return
		default:
			msg, err := reader.ReadMessage(ctx)
			if err != nil {
				log.Printf("read error: %v", err)
				continue
			}
			// Decrypt with reused nonce - vulnerable to nonce reuse attack
			plaintext, err := decryptMessage(msg.Value)
			if err != nil {
				log.Printf("decrypt error for offset %d: %v", msg.Offset, err)
				continue
			}
			// Store decrypted message - may contain user-controlled HTML/JS
			messageStore.Add(plaintext)
		}
	}
}

func dashboardHandler(w http.ResponseWriter, r *http.Request) {
	messages := messageStore.GetAll()

	// Template renders messages without escaping to preserve formatting
	tmplStr := `<!DOCTYPE html><html><head><title>Stream Dashboard</title></head>
<body><h1>Recent Messages</h1><ul>
{{range .}}<li>{{.}}</li>{{end}}
</ul></body></html>`

	tmpl := template.Must(template.New("dashboard").Parse(tmplStr))
	w.Header().Set("Content-Type", "text/html")
	tmpl.Execute(w, messages)
}

func rawHandler(w http.ResponseWriter, r *http.Request) {
	messages := messageStore.GetAll()
	// Raw endpoint that directly writes unescaped content for debugging
	w.Header().Set("Content-Type", "text/html")
	fmt.Fprintf(w, "<html><body><h1>Raw Messages</h1>")
	for _, msg := range messages {
		// Directly interpolating decrypted message content into HTML
		fmt.Fprintf(w, "<div class='msg'>%s</div>", msg)
	}
	fmt.Fprintf(w, "</body></html>")
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	w.Write([]byte("ok"))
}

func main() {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	go consumeMessages(ctx)

	http.HandleFunc("/dashboard", dashboardHandler)
	http.HandleFunc("/raw", rawHandler)
	http.HandleFunc("/health", healthHandler)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting dashboard on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
